CREATE SCHEMA IF NOT EXISTS my_car;
SET search_path TO my_car;
CREATE TABLE IF NOT EXISTS cars ("id" bigserial PRIMARY KEY,"manufacturer" text NOT NULL DEFAULT '',"model" text NOT NULL DEFAULT '',"price" numeric(14,2) NOT NULL DEFAULT 0,"condition" text NOT NULL DEFAULT '',"phone" text NOT NULL DEFAULT '',"email" text NOT NULL DEFAULT '',"speed" text NOT NULL DEFAULT '',"mileage" text NOT NULL DEFAULT '',"battery" text NOT NULL DEFAULT '',"fuel" text NOT NULL DEFAULT '',"total_run" text NOT NULL DEFAULT '',"gear" text NOT NULL DEFAULT '',"image" text NOT NULL DEFAULT '',"car_type" text NOT NULL DEFAULT '',"stock" bigint NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS cart ("id" bigserial PRIMARY KEY,"product_name" text NOT NULL DEFAULT '',"user_id" bigint NOT NULL DEFAULT 0,"product_id" bigint NOT NULL DEFAULT 0,"product_price" numeric(14,2) NOT NULL DEFAULT 0,"user_name" text NOT NULL DEFAULT '',"product_model" text NOT NULL DEFAULT '',"user_email" text NOT NULL DEFAULT '',"product_image" text NOT NULL DEFAULT '',"product_id_2" bigint NOT NULL DEFAULT -1);
CREATE TABLE IF NOT EXISTS gallary ("image1" text NOT NULL DEFAULT '',"image2" text NOT NULL DEFAULT '',"image3" text NOT NULL DEFAULT '',"image4" text NOT NULL DEFAULT '',"image5" text NOT NULL DEFAULT '',"image6" text NOT NULL DEFAULT '',"image7" text NOT NULL DEFAULT '',"id" bigserial PRIMARY KEY);
CREATE TABLE IF NOT EXISTS my_thoughts ("id" bigserial PRIMARY KEY,"title" text NOT NULL DEFAULT '',"body" text NOT NULL DEFAULT '',"image" text NOT NULL DEFAULT '',"create_time" timestamp NOT NULL DEFAULT now(),"tag" text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS orders ("id" bigserial PRIMARY KEY,"user_id" bigint NOT NULL DEFAULT 0,"address" text NOT NULL DEFAULT '',"city" text NOT NULL DEFAULT '',"phone" text NOT NULL DEFAULT '',"postal_code" text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS order_items ("id" bigserial PRIMARY KEY,"order_id" bigint NOT NULL DEFAULT 0,"product_id" bigint NOT NULL DEFAULT -1,"product_id2" bigint NOT NULL DEFAULT -1,manufacturer text NOT NULL DEFAULT '',model text NOT NULL DEFAULT '',price numeric(14,2) NOT NULL DEFAULT 0,image text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS products ("id" bigserial PRIMARY KEY,"manufacturer" text NOT NULL DEFAULT '',"model" text NOT NULL DEFAULT '',"price" numeric(14,2) NOT NULL DEFAULT 0,"type" text NOT NULL DEFAULT '',"image" text NOT NULL DEFAULT '',"condition" text NOT NULL DEFAULT '',"email" text NOT NULL DEFAULT '',"phone" text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS stories ("id" bigserial PRIMARY KEY,"title" text NOT NULL DEFAULT '',"body" text NOT NULL DEFAULT '',"showing" bigint NOT NULL DEFAULT 0,image text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS users ("id" bigserial PRIMARY KEY,"username" text NOT NULL DEFAULT '',"email" text NOT NULL DEFAULT '',"password" text NOT NULL DEFAULT '',"admin" bigint NOT NULL DEFAULT 0,cart bigint NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS users_email_unique ON users (lower(email));
CREATE TABLE IF NOT EXISTS sessions(id text PRIMARY KEY,content text NOT NULL,expires_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS uploaded_images(path text PRIMARY KEY,mime text NOT NULL,content text NOT NULL);
CREATE TABLE IF NOT EXISTS auth_attempts(key text NOT NULL,period bigint NOT NULL,count bigint NOT NULL,PRIMARY KEY(key,period));
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cart_user_fk' AND connamespace='my_car'::regnamespace) THEN ALTER TABLE cart ADD CONSTRAINT cart_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='orders_user_fk' AND connamespace='my_car'::regnamespace) THEN ALTER TABLE orders ADD CONSTRAINT orders_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='order_items_order_fk' AND connamespace='my_car'::regnamespace) THEN ALTER TABLE order_items ADD CONSTRAINT order_items_order_fk FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE; END IF; END $$;
